function isLoanTx(t){return !!t&&(t.kind==='loan'||t.kind==='loanPayment'||!!t.loanRecord)}
function blockLoanTx(t){if(t?.stmtInst){alert('這是帳單分期的記錄，請到信用卡明細的「帳單分期」取消整組。');return true}if(!isLoanTx(t))return false;alert('這是借還款交易，請到「借還款」頁面處理（收款／還款、停止追蹤）。\n直接在交易明細編輯或刪除，會造成借還款金額與帳戶餘額不一致。');return true}
async function deleteTx(id){let t=state.transactions.find(x=>String(x.id)===String(id));if(!t)return;if(blockLoanTx(t))return;if(t.installment){const ids=installmentDeleteChoice(t);if(!ids)return;for(const x of state.transactions.filter(x=>ids.includes(String(x.id))))adjust(x,-1);state.transactions=state.transactions.filter(x=>!ids.includes(String(x.id)));await save();detailBg.classList.remove('open');render();return}if(!confirm(`確定刪除「${t.name}」${money(t.amount)}？`))return;adjust(t,-1);state.transactions=state.transactions.filter(x=>String(x.id)!==String(id));txAfterDelete(t);await save();detailBg.classList.remove('open');render()}
