    if (a === 'new') R.edit = { filter: {} }; else if (a === 'edit') R.edit = d; else if (a === 'copy') { const n = { ...JSON.parse(JSON.stringify(d)), id: id(), name: `${d.name} 複製`.slice(0, 20) }; setPref('reports', [...l, n]); R.id = n.id; }
